service.method:

SELECT
	DEPT
FROM
	SDEPT
WHERE
		HOUSE_CODE 		= ${session.HOUSE_CODE}
	AND COMPANY_CODE 	= ${session.COMPANY_CODE}	
	AND DEPT 			= ${DEPT}


UPDATE SDEPT
	SET
		  DEPT_NAME_LOC	  = ${DEPT_NAME_LOC}
		, PARENT_DEPT	  = ${PARENT_DEPT}
		, DEL_FLAG		  = 'N'
		, CHANGE_DATE     = ${current.DATE}
		, CHANGE_TIME     = ${current.TIME}
		, CHANGE_USER_ID  = ${session.ID}
		, DEPTH           = $S{DEPTH}
		, MANAGER_ID      = $S{MANAGER_ID}
WHERE
		HOUSE_CODE        = ${session.HOUSE_CODE}
		AND COMPANY_CODE  = ${session.COMPANY_CODE}
		AND DEPT		  = ${DEPT}


INSERT INTO SDEPT
	(
		  HOUSE_CODE
		, COMPANY_CODE
		, DEPT
		, DEPT_NAME_LOC
		, ADD_DATE
		, ADD_TIME
		, ADD_USER_ID				
		, PARENT_DEPT
		, DEL_FLAG
		, DEPTH
		, MANAGER_ID
	)
	VALUES
	(
		  ${session.HOUSE_CODE}
		, ${session.COMPANY_CODE}
		, ${DEPT}
		, ${DEPT_NAME_LOC}
		, ${current.DATE}
		, ${current.TIME}
		, ${session.ID}				
		, #DB_OWNER#NVL(${PARENT_DEPT}, PARENT_DEPT)
		, 'N'
		, #DB_OWNER#NVL(${DEPTH}, DEPTH)
		, #DB_OWNER#NVL(${MANAGER_ID}, MANAGER_ID)
	)
